126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * Establishes the effective registration date at persist time, so the create-time default
135	     * applies to any persistence path.
136	     */
137	    @PrePersist
138	    protected void defaultRegistrationDate() {
139	        resolveRegistrationDate();
140	    }
141	
142	    /**
143	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
144	     * the server's current date when none was supplied, and the result is rolled forward onto a
145	     * business day (a Saturday or Sunday becomes the following Monday). Returns the resolved date.
146	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
147	     */
148	    public LocalDate resolveRegistrationDate() {
149	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
150	        this.registrationDate = toBusinessDay(effective);
151	        return this.registrationDate;
152	    }
153	
154	    /**
155	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
156	     * following Monday, while any weekday (and {@code null}) is returned unchanged. Applying this to a
157	     * date that is already a business day is a no-op, so it is safe to call more than once.
158	     */
159	    public static LocalDate toBusinessDay(LocalDate date) {
160	        if (date == null) {
161	            return null;
162	        }
163	        return switch (date.getDayOfWeek()) {
164	            case SATURDAY -> date.plusDays(2);
165	            case SUNDAY -> date.plusDays(1);
166	            default -> date;
167	        };
168	    }
169	
170	    protected Set<Pet> getPetsInternal() {
171	        if (this.pets == null) {
172	            this.pets = new HashSet<>();
173	        }
174	        return this.pets;
175	    }
176	
177	    protected void setPetsInternal(Set<Pet> pets) {
178	        this.pets = pets;
179	    }
180	
181	    public List<Pet> getPets() {
182	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
183	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
184	        return Collections.unmodifiableList(sortedPets);
185	    }
186	
187	    public void setPets(List<Pet> pets) {
188	        this.pets = new HashSet<>(pets);
189	    }
190	
191	    public void addPet(Pet pet) {
192	        getPetsInternal().add(pet);
193	        pet.setOwner(this);
194	    }
195	
196	    /**
197	     * Return the Pet with the given name, or null if none found for this Owner.
198	     *
199	     * @param name to test
200	     * @return true if pet name is already in use
201	     */
202	    public Pet getPet(String name) {
203	        return getPet(name, false);
